// timeline.ts — EVERY time value is derived from the SRT cues (src/cues.ts, generated by scripts/srt-to-cues.mjs).
// Where one cue holds several things (e.g. "অর্থ … Sentence চার"), the cue is divided in proportion to the text
// length of each part (weights below = character counts of each part in the cue).
import { CUES } from "./cues";

export const FPS = 30;
export const LEAD = 5; // visuals enter 4–6 frames before the spoken words
export const OVERLAP = 8; // soft scene transitions overlap this many frames

const cue = (i: number) => CUES[i - 1];
const split = (i: number, w: number[]): number[] => {
  const { s, e } = cue(i);
  const total = w.reduce((a, b) => a + b, 0);
  let acc = 0;
  return w.map((x) => { const t = s + ((e - s) * acc) / total; acc += x; return t; });
};
export const f = (sec: number) => Math.round(sec * FPS); // speech frame
export const ev = (sec: number) => Math.max(0, f(sec) - LEAD); // visual-entrance frame

export const DURATION = f(CUES[CUES.length - 1].e + 0.4);

// ---------- named moments (seconds) ----------
const hook = split(1, [47, 10]); // [question starts, "চিন্তা নেই"]
const intro = split(2, [21, 31, 19, 9]); // [৩০ দিন, ৩০০ বাক্য, আজ প্রথম ১০টি, চলুন শুরু]
const lessonBasic = split(5, [18, 21, 14, 20]); // [Basic Conversation, বলুন, শুনুন, মুখস্থ]
const c18 = split(18, [13, 13]); // [S3 meaning, S4 label]
const c19 = split(19, [9, 9, 19]); // [S4 phrase, repeat, meaning]
const c27 = split(27, [22, 13]); // [S6 meaning, S7 label]
const c29 = split(29, [19, 17]); // [S7 repeat, S7 meaning]
const c26 = split(26, [17, 5]); // [S6 repeat, "অর্থ"]
const c36 = split(36, [27, 31, 12]); // [S9 repeat, S9 meaning, S10 label]
const c39 = split(39, [22, 45, 11]); // [S10 meaning, congrats, "মনে রাখবেন"]
const c40 = split(40, [21, 30, 26]); // [৩০ দিনে ৩০০টি, ফলো করুন, কমেন্টে লিখুন]
const c41 = split(41, [5, 28]); // [Done, দেখা হবে…]

export type Sent = { n: number; L: number; P: number; Pe: number; R: number; Re: number; M: number; Say?: number; SayEnd?: number };
export const SENT: Sent[] = [
  { n: 1, L: cue(6).s, P: cue(7).s, Pe: cue(7).e, R: cue(8).s, Re: cue(8).e, M: cue(9).s, Say: cue(10).s, SayEnd: cue(10).e },
  { n: 2, L: cue(11).s, P: cue(12).s, Pe: cue(12).e, R: cue(13).s, Re: cue(13).e, M: cue(14).s },
  { n: 3, L: cue(15).s, P: cue(16).s, Pe: cue(16).e, R: cue(17).s, Re: cue(17).e, M: c18[0] },
  { n: 4, L: c18[1], P: c19[0], Pe: c19[1], R: c19[1], Re: c19[2], M: c19[2] },
  { n: 5, L: cue(20).s, P: cue(21).s, Pe: cue(21).e, R: cue(22).s, Re: cue(22).e, M: cue(23).s },
  { n: 6, L: cue(24).s, P: cue(25).s, Pe: cue(25).e, R: cue(26).s, Re: c26[1], M: c27[0] },
  { n: 7, L: c27[1], P: cue(28).s, Pe: cue(28).e, R: c29[0], Re: c29[1], M: c29[1] },
  { n: 8, L: cue(30).s, P: cue(31).s, Pe: cue(31).e, R: cue(32).s, Re: cue(32).e, M: cue(33).s },
  { n: 9, L: cue(34).s, P: cue(35).s, Pe: cue(35).e, R: c36[0], Re: c36[1], M: c36[1] },
  { n: 10, L: c36[2], P: cue(37).s, Pe: cue(37).e, R: cue(38).s, Re: cue(38).e, M: c39[0] },
];

export const T = {
  hook: { start: hook[0], chinta: hook[1] },
  intro: { start: cue(2).s, d30: intro[0], d300: intro[1], today: intro[2], go: intro[3] },
  lesson: { start: cue(4).s, basic: lessonBasic[0], speak: lessonBasic[1], listen: lessonBasic[2], memorize: lessonBasic[3] },
  recap: { start: c39[1], remember: c39[2] },
  progress: { start: c40[0] },
  cta: { start: c40[1], comment: c40[2] },
  outro: { start: c41[0], meet: c41[1] },
};

// ---------- scenes ----------
type Def = { id: string; start: number; wipe: boolean }; // wipe = transition INTO this scene is a colour wipe
const defs: Def[] = [
  { id: "hook", start: 0, wipe: false },
  { id: "intro", start: T.intro.start, wipe: true },
  { id: "lesson", start: T.lesson.start, wipe: false },
  ...SENT.map((s, i) => ({ id: `s${s.n}`, start: s.L, wipe: i === 0 })),
  { id: "recap", start: T.recap.start, wipe: true },
  { id: "progress", start: T.progress.start, wipe: false },
  { id: "cta", start: T.cta.start, wipe: false },
  { id: "outro", start: T.outro.start, wipe: true },
];
export type SceneInfo = { id: string; from: number; to: number; wipeNext: boolean; wipeBefore: boolean };
export const SCENES: SceneInfo[] = defs.map((d, i) => {
  const from = i === 0 ? 0 : ev(d.start);
  const next = defs[i + 1];
  const wipeNext = !!next?.wipe;
  const to = next ? ev(next.start) + (wipeNext ? 0 : OVERLAP) : DURATION;
  return { id: d.id, from, to, wipeNext, wipeBefore: d.wipe };
});
export const scene = (id: string) => SCENES.find((s) => s.id === id)!;
export const WIPES = SCENES.filter((s) => s.wipeBefore).map((s) => s.from);

// ---------- derived interaction frames shared by visuals + SFX ----------
export const CTA = {
  followPress: ev(T.cta.start) + 20,
  typeStart: ev(T.cta.comment) + 14,
  perChar: 3,
  text: "DAY 1 DONE!",
  get sendPress() { return this.typeStart + this.text.length * this.perChar + 10; },
};
export const RECAP = { per: 5, checkDelay: 9 }; // grid stagger
export const recapLastCheck = ev(T.recap.start) + 9 * RECAP.per + RECAP.checkDelay + 6;

// ---------- SFX events (absolute frames) ----------
export type SfxEvent = { at: number; name: "pop" | "click" | "thud" | "chime" | "whoosh" | "swipe"; vol?: number };
export const SFX: SfxEvent[] = (() => {
  const out: SfxEvent[] = [];
  // hook
  out.push({ at: 2, name: "whoosh", vol: 0.9 });
  out.push({ at: ev(T.hook.chinta) + 2, name: "thud", vol: 1 });
  // transitions
  SCENES.forEach((s, i) => {
    if (i === 0) return;
    out.push(s.wipeBefore ? { at: Math.max(0, s.from - 12), name: "whoosh", vol: 0.85 } : { at: Math.max(0, s.from - 2), name: "swipe", vol: 0.8 });
  });
  // intro
  out.push({ at: ev(T.intro.d30), name: "pop" });
  out.push({ at: ev(T.intro.d300), name: "pop" });
  out.push({ at: ev(T.intro.today), name: "click" });
  // lesson
  out.push({ at: ev(T.lesson.basic), name: "whoosh", vol: 0.8 });
  [T.lesson.speak, T.lesson.listen, T.lesson.memorize].forEach((t) => out.push({ at: ev(t), name: "pop" }));
  // sentences
  SENT.forEach((s) => {
    out.push({ at: ev(s.P), name: "pop" });
    out.push({ at: ev(s.R), name: "click" });
    out.push({ at: ev(s.M), name: "chime" });
    if (s.Say) out.push({ at: ev(s.Say), name: "pop" });
  });
  // recap / progress / cta / outro
  out.push({ at: ev(T.recap.start) + 2, name: "pop" });
  out.push({ at: recapLastCheck, name: "click" });
  out.push({ at: ev(T.progress.start) + 4, name: "pop" });
  out.push({ at: CTA.followPress, name: "click" });
  out.push({ at: ev(T.cta.comment), name: "pop" });
  out.push({ at: CTA.sendPress, name: "click" });
  out.push({ at: ev(T.outro.start) + 2, name: "chime" });
  out.push({ at: ev(T.outro.meet) + 4, name: "pop" });
  return out.sort((a, b) => a.at - b.at);
})();
